INSERT INTO `lyric_lines` (`id`,`section_id`,`sequence`,`language`,`text`,`review_status`) VALUES
  ('002-v1-zh-1','002-v1',1,'zh-Hant','全能君王我神！','canonical'),
  ('002-v1-zh-2','002-v1',2,'zh-Hant','教我頌讚你名，','canonical'),
  ('002-v1-zh-3','002-v1',3,'zh-Hant','頌讚不停：','canonical'),
  ('002-v1-zh-4','002-v1',4,'zh-Hant','讚美父神尊榮，','canonical'),
  ('002-v1-zh-5','002-v1',5,'zh-Hant','讚你超越得勝，','canonical'),
  ('002-v1-zh-6','002-v1',6,'zh-Hant','讚你權能統治，','canonical'),
  ('002-v1-zh-7','002-v1',7,'zh-Hant','直到永世。','canonical'),
  ('002-v1-en-1','002-v1',1,'en','Come, Thou Almighty King,','canonical'),
  ('002-v1-en-2','002-v1',2,'en','Help us Thy name to sing,','canonical'),
  ('002-v1-en-3','002-v1',3,'en','Help us to praise.','canonical'),
  ('002-v1-en-4','002-v1',4,'en','Father, all glorious,','canonical'),
  ('002-v1-en-5','002-v1',5,'en','O’er all victorious,','canonical'),
  ('002-v1-en-6','002-v1',6,'en','Come, and reign over us,','canonical'),
  ('002-v1-en-7','002-v1',7,'en','Ancient of Days.','canonical'),
  ('002-v2-zh-1','002-v2',1,'zh-Hant','神子成了肉身！','canonical'),
  ('002-v2-zh-2','002-v2',2,'zh-Hant','顯出無限權能，','canonical'),
  ('002-v2-zh-3','002-v2',3,'zh-Hant','聽我呼聲：','canonical'),
  ('002-v2-zh-4','002-v2',4,'zh-Hant','賜你子民福分，','canonical'),
  ('002-v2-zh-5','002-v2',5,'zh-Hant','使你應許得成——','canonical'),
  ('002-v2-zh-6','002-v2',6,'zh-Hant','降下聖潔之靈，','canonical'),
  ('002-v2-zh-7','002-v2',7,'zh-Hant','使我成聖。','canonical'),
  ('002-v2-en-1','002-v2',1,'en','Come, Thou incarnate Word,','canonical'),
  ('002-v2-en-2','002-v2',2,'en','Gird on Thy mighty sword,','canonical'),
  ('002-v2-en-3','002-v2',3,'en','Our prayer attend:','canonical'),
  ('002-v2-en-4','002-v2',4,'en','Come, and Thy people bless,','canonical'),
  ('002-v2-en-5','002-v2',5,'en','And give Thy word success;','canonical'),
  ('002-v2-en-6','002-v2',6,'en','Spirit of holiness,','canonical'),
  ('002-v2-en-7','002-v2',7,'en','On us descend.','canonical'),
  ('002-v3-zh-1','002-v3',1,'zh-Hant','保惠之靈降臨！','canonical'),
  ('002-v3-zh-2','002-v3',2,'zh-Hant','負起神聖見證，','canonical'),
  ('002-v3-zh-3','002-v3',3,'zh-Hant','在此良辰：','canonical'),
  ('002-v3-zh-4','002-v3',4,'zh-Hant','以你生命大能，','canonical'),
  ('002-v3-zh-5','002-v3',5,'zh-Hant','在我心中執政，','canonical'),
  ('002-v3-zh-6','002-v3',6,'zh-Hant','永遠住我裏面，','canonical'),
  ('002-v3-zh-7','002-v3',7,'zh-Hant','運行、成全。','canonical'),
  ('002-v3-en-1','002-v3',1,'en','Come, holy Comforter,','canonical'),
  ('002-v3-en-2','002-v3',2,'en','Thy sacred witness bear','canonical'),
  ('002-v3-en-3','002-v3',3,'en','In this glad hour:','canonical'),
  ('002-v3-en-4','002-v3',4,'en','Thou who Almighty art,','canonical'),
  ('002-v3-en-5','002-v3',5,'en','Now rule in every heart,','canonical'),
  ('002-v3-en-6','002-v3',6,'en','And ne’er from us depart,','canonical'),
  ('002-v3-en-7','002-v3',7,'en','Spirit of power.','canonical'),
  ('002-v4-zh-1','002-v4',1,'zh-Hant','大哉，三一之神！','canonical'),
  ('002-v4-zh-2','002-v4',2,'zh-Hant','永遠配得稱頌，','canonical'),
  ('002-v4-zh-3','002-v4',3,'zh-Hant','永世無終！','canonical'),
  ('002-v4-zh-4','002-v4',4,'zh-Hant','直到榮耀之中，','canonical'),
  ('002-v4-zh-5','002-v4',5,'zh-Hant','瞻你無上尊榮，','canonical'),
  ('002-v4-zh-6','002-v4',6,'zh-Hant','獻上愛戴、尊敬，','canonical'),
  ('002-v4-zh-7','002-v4',7,'zh-Hant','永無止境！','canonical'),
  ('002-v4-en-1','002-v4',1,'en','To Thee, great One in Three,','canonical'),
  ('002-v4-en-2','002-v4',2,'en','Eternal praises be','canonical'),
  ('002-v4-en-3','002-v4',3,'en','Hence evermore.','canonical'),
  ('002-v4-en-4','002-v4',4,'en','Thy sov’reign majesty','canonical'),
  ('002-v4-en-5','002-v4',5,'en','May we in glory see,','canonical'),
  ('002-v4-en-6','002-v4',6,'en','And to eternity','canonical'),
  ('002-v4-en-7','002-v4',7,'en','Love and adore.','canonical');
INSERT INTO `lyric_lines` (`id`,`section_id`,`sequence`,`language`,`text`,`review_status`) VALUES
  ('175-v1-zh-1','175-v1',1,'zh-Hant','有一生命江河——從我裏湧流，','canonical'),
  ('175-v1-zh-2','175-v1',2,'zh-Hant','叫瞎眼的看見、叫瘸子行走；','canonical'),
  ('175-v1-zh-3','175-v1',3,'zh-Hant','打開監獄的門——釋放被囚。','canonical'),
  ('175-v1-zh-4','175-v1',4,'zh-Hant','有一生命江河——從我裏湧流。','canonical'),
  ('175-v1-en-1','175-v1',1,'en','There’s a river of life flowing out thru me,','canonical'),
  ('175-v1-en-2','175-v1',2,'en','It makes the lame to walk and the blind to see;','canonical'),
  ('175-v1-en-3','175-v1',3,'en','Opens prison doors, sets the captives free,','canonical'),
  ('175-v1-en-4','175-v1',4,'en','There’s a river of life flowing out thru me.','canonical'),
  ('175-v2-zh-1','175-v2',1,'zh-Hant','有一泉源流自救主的肋旁，','canonical'),
  ('175-v2-zh-2','175-v2',2,'zh-Hant','這寶血洗淨我，從罪得釋放；','canonical'),
  ('175-v2-zh-3','175-v2',3,'zh-Hant','耶穌付贖價——祂為我而亡。','canonical'),
  ('175-v2-zh-4','175-v2',4,'zh-Hant','有一泉源流自救主的肋旁。','canonical'),
  ('175-v2-en-1','175-v2',1,'en','There’s a fountain flowing from the Savior’s side,','canonical'),
  ('175-v2-en-2','175-v2',2,'en','All my sin’s forgiven in that precious tide;','canonical'),
  ('175-v2-en-3','175-v2',3,'en','Jesus paid the price. When for me He died,','canonical'),
  ('175-v2-en-4','175-v2',4,'en','There’s a fountain flowing from the Savior’s side.','canonical'),
  ('175-v3-zh-1','175-v3',1,'zh-Hant','有一復活救主在父寶座前，','canonical'),
  ('175-v3-zh-2','175-v3',2,'zh-Hant','不斷為祂的人代求父赦免；','canonical'),
  ('175-v3-zh-3','175-v3',3,'zh-Hant','傾倒祂祝福並豐富恩典。','canonical'),
  ('175-v3-zh-4','175-v3',4,'zh-Hant','有一復活救主在父寶座前。','canonical'),
  ('175-v3-en-1','175-v3',1,'en','There’s a risen Savior at the Father’s throne,','canonical'),
  ('175-v3-en-2','175-v3',2,'en','Ever interceding for His very own;','canonical'),
  ('175-v3-en-3','175-v3',3,'en','Pouring down the blessings that are His alone,','canonical'),
  ('175-v3-en-4','175-v3',4,'en','There’s a risen Savior at the Father’s throne.','canonical'),
  ('175-v4-zh-1','175-v4',1,'zh-Hant','有一位保惠師，祂來自天上，','canonical'),
  ('175-v4-zh-2','175-v4',2,'zh-Hant','賜下祂的一切榮耀的恩賞；','canonical'),
  ('175-v4-zh-3','175-v4',3,'zh-Hant','除去我帕子，啟示主榮光。','canonical'),
  ('175-v4-zh-4','175-v4',4,'zh-Hant','有一位保惠師，祂來自天上。','canonical'),
  ('175-v4-en-1','175-v4',1,'en','There’s a holy Comforter who’s sent from heaven,','canonical'),
  ('175-v4-en-2','175-v4',2,'en','All the glorious gifts are His, and have been given.','canonical'),
  ('175-v4-en-3','175-v4',3,'en','He’ll show us more of Jesus ’til the veil is riven.','canonical'),
  ('175-v4-en-4','175-v4',4,'en','There’s a holy Comforter who’s sent from heaven.','canonical'),
  ('175-v5-zh-1','175-v5',1,'zh-Hant','有一安息之地今我能進入，','canonical'),
  ('175-v5-zh-2','175-v5',2,'zh-Hant','不再勞苦、不再受撒但欺侮；','canonical'),
  ('175-v5-zh-3','175-v5',3,'zh-Hant','只須每時刻安息於我主。','canonical'),
  ('175-v5-zh-4','175-v5',4,'zh-Hant','有一安息之地我今能進入。','canonical'),
  ('175-v5-en-1','175-v5',1,'en','There’s a land of rest that we may enter now,','canonical'),
  ('175-v5-en-2','175-v5',2,'en','Freed from all our works and freed from Satan’s power,','canonical'),
  ('175-v5-en-3','175-v5',3,'en','Just resting in the Lord each moment and each hour.','canonical'),
  ('175-v5-en-4','175-v5',4,'en','There’s a land of rest that we may enter now.','canonical'),
  ('175-v6-zh-1','175-v6',1,'zh-Hant','有一完全救恩為著你和我，','canonical'),
  ('175-v6-zh-2','175-v6',2,'zh-Hant','藉信以致於信，榮耀且豐博；','canonical'),
  ('175-v6-zh-3','175-v6',3,'zh-Hant','哦，獻上我命為主而生活，','canonical'),
  ('175-v6-zh-4','175-v6',4,'zh-Hant','有一完全救恩為著你和我。','canonical'),
  ('175-v6-en-1','175-v6',1,'en','There’s a full salvation wrought for you and me,','canonical'),
  ('175-v6-en-2','175-v6',2,'en','From faith to faith and glory to glory eternally,','canonical'),
  ('175-v6-en-3','175-v6',3,'en','O Lord, just take this life and let me live for thee,','canonical'),
  ('175-v6-en-4','175-v6',4,'en','There’s a full salvation wrought for you and me.','canonical'),
  ('175-c-zh-1','175-chorus',1,'zh-Hant','我的井阿！在我裏面！','canonical'),
  ('175-c-zh-2','175-chorus',2,'zh-Hant','湧上水來！使我痊癒；','canonical'),
  ('175-c-zh-3','175-chorus',3,'zh-Hant','我的井阿！湧上水來！','canonical'),
  ('175-c-zh-4','175-chorus',4,'zh-Hant','生命豐滿有餘。','canonical'),
  ('175-c-en-1','175-chorus',1,'en','Spring up, O well, within my soul,','canonical'),
  ('175-c-en-2','175-chorus',2,'en','Spring up, O well, and make me whole;','canonical'),
  ('175-c-en-3','175-chorus',3,'en','Spring up, O well, and give to me','canonical'),
  ('175-c-en-4','175-chorus',4,'en','That life abundantly.','canonical');
